// toMSSQLConn asserts the given connection is a *mssql.Conn and returns its
// underlying connection along with the login flags returned by the server so
// that they can be passed back to the client.
func toMSSQLConn(conn net.Conn) (io.ReadWriteCloser, []mssql.Token, error) {
	mssqlConn, ok := conn.(*mssql.Conn)
	if !ok {
		return nil, nil, trace.BadParameter("expected *mssql.Conn, got: %T", conn)
	}

	return mssqlConn.GetUnderlyingConn(), mssqlConn.GetLoginFlags(), nil
}

